"""Editorial report data; recommendations are analysis, not automatically adopted rules."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
meta={r['repository']:r for r in json.loads((HERE/'research/primary-sources.json').read_text())}
experts=[]
def add(id,name,field,position,repo,summary,evidence,good,bad,rules,sources=(),boundary=None):
 m=meta[repo];commit=m['commits'][0]
 experts.append(dict(id=id,name=name,field=field,position=position,summary=summary,evidence=evidence,
 boundary=boundary or '근거 범위: 공개 문서와 저장소 변경 메타데이터. 비공개 개인 대화·전체 개발 이력은 확보하지 않았습니다. 아래 장단점과 권고는 이 프로젝트에 대한 분석입니다.',
 good=good,bad=bad,rules=[dict(id=id+'-'+str(i+1),title=t,rule=r,when=w,test=test,recommendation=rec) for i,(t,r,w,test,rec) in enumerate(rules)],
 sources=[dict(title='공개 저장소와 현재 README',url=m['url']),*map(lambda s:dict(title=s[0],url=s[1]),sources)],
 action=dict(description=f"{commit['date'][:10]} · {commit['author']} 명의 변경: {commit['message']}. 이 항목은 공개 커밋의 제목·작성자·시각을 확인한 것이며 실제 전체 회귀 검사 성공을 의미하지 않습니다.",label='커밋 원문 확인',url=commit['url']),
 license=f"저장소 라이선스 메타데이터: {m['license'] or '확인되지 않음'}. 최근 push: {m['updated_at'][:10]}. 공개 글·강의·상용 제품의 권리는 별도이며 공개 열람 가능 여부가 재배포 허가를 뜻하지 않습니다. 이 보고서는 원문 코드를 반입하지 않았습니다."))
add('garry','Garry Tan','개발 흐름 · 제품 정의 · 실제 QA','gstack 작성자. 본인이 사용하는 개발 흐름을 역할별 스킬로 공개.','garrytan/gstack',
 '요구사항을 다시 묻는 단계, 엔지니어링 검토, 코드 리뷰, 실제 실행 검증을 연결하는 기본 골격으로 적합합니다. 이미 선택하신 gstack 기반을 유지하되 작업 크기에 맞춰 필요한 단계만 사용하길 권합니다.',
 'README는 본인의 일상 개발에 사용한다고 밝히며 office-hours, review, qa를 시작점으로 제시합니다. 현재 Cursor는 experimental 등급입니다. 역할 구성은 공개돼 있지만 개인 생산성 주장에 대한 독립 검증은 하지 않았습니다.',
 ['제품의 목적과 구현할 기능을 함께 점검해 요구사항 누락을 줄일 수 있습니다.','코드 리뷰와 실제 브라우저 검증을 분리해 “컴파일되면 완료”로 끝나는 것을 막습니다.','역할별 스킬을 필요할 때 읽는 구성이 전문 지식의 선택적 호출과 맞습니다.'],
 ['작은 변경에도 모든 역할을 순서대로 호출하면 대기·토큰·반복 문서가 늘어납니다.','제품 방향을 재해석하는 과정이 사용자의 명시적 의도를 바꿔 버리지 않게 해야 합니다.','실험적 Cursor 지원과 별도 도구 의존성을 운영 검증 완료로 간주하면 안 됩니다.'],[
 ('요구사항을 성공 조건으로 연결','깊이 있는 대화에서 사용자·행동·성공 결과·예외를 정리하고 구현 및 검증 항목으로 연결합니다.','신규 기능 또는 목표가 모호할 때. 이미 정해진 작은 변경은 바로 진행.','주요 요구사항마다 관찰 가능한 인수 조건이 있는지 확인.','채택 후보'),
 ('리뷰와 실제 시나리오 QA 분리','정적 리뷰 후 중요한 행동을 실제 실행해 결과와 오류·캡처를 남깁니다.','업무 흐름, 데이터 변경, 신규 화면. 문구 수정에는 필요한 확인만.','보여야 할 화면뿐 아니라 행동·권한·실패 결과를 검증.','채택 후보'),
 ('전체 역할 호출을 기본 의무로 만들지 않기','작업 규모에 맞는 경로만 택하고 동일 목적의 계획·리뷰·QA를 중복 실행하지 않습니다.','gstack과 별도 UI/QA 플러그인을 함께 사용할 때.','작은 버그 수정에 불필요한 승인/설계 반복이 없는지 확인.','프로젝트 맞춤 해석')], [('호스트별 지원·설치 원문','https://github.com/garrytan/gstack#other-ai-agents')])
add('mario','Mario Zechner','에이전트 하네스 · 컨텍스트 · 세션','Pi 작성자. 2025년 직접 만든 이유와 설계 선택을 공개 글로 설명.','earendil-works/pi',
 '에이전트를 크게 만드는 것보다 입력 컨텍스트와 세션을 관찰 가능하게 만드는 접근이 개인화 기반에 유용합니다. 다만 Pi의 최소 구성이나 실행 권한을 그대로 채택할 필요는 없습니다.',
 '2025-11-30 글에서 숨은 컨텍스트 주입과 도구 변경에 대한 불만, 상호작용 관찰·후처리 가능한 세션 형식을 요구한 배경을 설명합니다. 현재 저장소는 확장·스킬·RPC·SDK를 제공합니다. 옛 글의 “없는 기능” 목록을 최신 API 목록으로 사용하지 않았습니다.',
 ['개인 피드백의 원문·전환·도구 결과를 보존하는 근거 저장 구조와 잘 맞습니다.','작은 코어와 확장 지점을 분리하면 선호 규칙이 늘어도 기본 실행기를 비대하게 만들지 않습니다.'],
 ['당시 글의 YOLO 기본값이나 계획 도구 최소화를 현재 개인 앱의 기본 권한 정책으로 옮기면 위험합니다.','컨텍스트를 줄이는 것 자체가 목표가 되면 요구사항·반례·실패 증거가 사라질 수 있습니다.'],[
 ('숨은 컨텍스트 대신 출처가 있는 입력','모델에 준 요구사항·참고 규칙·원문 근거의 출처와 버전을 기록합니다.','개인 규칙 검색과 Codex 기능별 세션을 구성할 때.','같은 결과를 만든 입력과 적용 규칙을 다시 확인할 수 있음.','채택 후보'),
 ('세션을 후처리 가능한 이벤트로 보존','요청과 응답·판단·결과를 구조화해 저장하고 업무 ID와 연결합니다.','회의별 resume, 피드백 수집, 실패 분석.','재시작 후 같은 업무의 세션을 이어가고 다른 업무와 섞이지 않음.','채택 후보'),
 ('최소 도구·넓은 실행 권한은 분리해서 판단','작은 도구 인터페이스는 참고하되 불필요한 파일·셸·외부 작업 권한은 자동 확대하지 않습니다.','Broker나 자동 개발 에이전트를 설계할 때.','실행 컨테이너의 접근 가능한 경로·권한을 직접 확인.','조건부')], [('작성자 직접 회고 · 2025-11-30','https://mariozechner.at/posts/2025-11-30-pi-coding-agent/')])
add('simon','Simon Willison','검증 · 관찰 가능성 · LLM 로그','LLM·Datasette 개발자. 공개 개발 글과 도구를 함께 유지.','simonw/llm',
 '실행 가능한 테스트·개발 서버·상세 오류와 로그를 에이전트에 제공하는 방식이 안정적인 자율 개발의 기반입니다. 모든 대화를 쌓는 것만으로 좋은 판단 규칙이 생기는 것은 별개입니다.',
 '2025-10-25 직접 작성한 글은 에이전트가 실행할 수 있는 테스트, Playwright/curl, 이슈, 린터와 구체적인 오류를 권합니다. LLM 도구는 대화 기록을 다루는 공개 구현 사례입니다. 최근 커밋의 작성자를 모두 Simon 본인으로 간주하지 않았습니다.',
 ['사용자 불만을 재현 가능한 실패 사례로 바꿔 수정 결과를 판정하기 좋습니다.','로그·오류·모델 사용량을 남기는 접근이 개인화의 근거와 비용 분석을 돕습니다.'],
 ['테스트가 통과해도 화면의 취향이나 핵심 행동의 편의성을 대신 평가하지는 못합니다.','원문 로그를 무제한 보존하면 비밀값·민감 정보·오래된 선호가 함께 누적됩니다.'],[
 ('버그 피드백을 재현 사례로 만들기','사용자가 지적한 실패를 구체적 입력·행동·예상 결과로 저장하고 수정 후 다시 실행합니다.','동작 버그와 반복된 회귀. 단순 문체 변경에는 과한 테스트를 만들지 않음.','수정 전 실패·수정 후 통과가 같은 조건에서 확인됨.','채택 후보'),
 ('실행 방법과 오류를 에이전트에 제공','서비스 시작, 필요한 검사 명령, 실패 맥락을 짧고 정확하게 제공합니다.','새 서비스·환경 복구·자동 개발.','별도 추측 없이 로컬/컨테이너에서 기능을 재현할 수 있음.','채택 후보'),
 ('로그 수집에 범위·보존·정제 적용','선택한 작업 로그만 수집하고 비밀값을 정제하며 출처·버전을 남깁니다.','개인 개발 기록과 대화 import.','중복 제거, 비밀값 제거, 프로젝트별 검색 격리 검증.','프로젝트 맞춤 해석')], [('작성자의 에이전트용 코드베이스 조언','https://simonwillison.net/2025/Oct/25/coding-agent-tips/'),('LLM 로그 문서','https://llm.datasette.io/en/stable/logging.html')])
add('tobi','Tobias Lütke','개인 지식 검색 · 근거 회수','QMD 공개 작성자. 로컬 문서·회의 기록 검색 도구.','tobi/qmd',
 '모든 경험을 매번 프롬프트에 넣기보다 지금 과업과 관련된 판단·근거만 찾아 넣는 데 적합합니다. 검색 결과를 사용자의 확정 선호로 자동 승격하면 안 됩니다.',
 'QMD는 로컬 BM25·벡터 검색·재정렬과 collection/context 구조를 문서화합니다. 공개 코드는 검색 설계를 보여 주지만 저자의 비공개 지식 저장소를 공개한 것은 아닙니다.',
 ['정확한 키워드와 표현이 다른 경험을 함께 찾는 방식이 피드백 재사용에 유용합니다.','프로젝트·자료 묶음별 맥락을 붙여 근거의 적용 조건을 보존할 수 있습니다.'],
 ['소량 자료에는 임베딩·reranker 모델이 불필요한 복잡도와 메모리를 추가할 수 있습니다.','잘 검색된 자료도 반례·시점·거절 여부가 누락되면 잘못된 규칙을 강화할 수 있습니다.'],[
 ('현재 과업에 관련된 근거만 회수','프로젝트·분야·판단 상태로 범위를 좁혀 과거 지적과 수정 결과를 검색합니다.','UI 재설계, 반복 업무, 개인 선호 반영.','반복 카드 금지 같은 실제 지적이 관련 요청에서 근거와 함께 검색됨.','채택 후보'),
 ('작게 시작하고 검색 성능을 보고 확장','처음에는 SQLite FTS와 구조화 필터를 쓰고 놓치는 근거가 확인되면 hybrid 검색을 검토합니다.','개인 기록 규모가 작거나 운영 부담을 줄일 때.','실제 질의 세트의 관련 근거 회수율과 지연 시간을 비교.','프로젝트 맞춤 해석'),
 ('원문 검색과 확정 규칙 구분','검색 결과에는 출처와 상태를 붙이고 채택된 규칙만 기본 지침 후보로 씁니다.','과거 발언이 상충하거나 특정 프로젝트에만 해당할 때.','거절/대체된 판단이 현재의 확정 선호로 삽입되지 않음.','프로젝트 맞춤 해석')])
add('jesse','Jesse Vincent','요구사항 대화 · TDD · 완료 검증','Superpowers 작성자. 개발 흐름을 조합 가능한 스킬로 공개.','obra/superpowers',
 '대화로 범위를 정한 뒤 실행 가능한 계획과 검증으로 이어가는 접근은 목표와 잘 맞습니다. 단계별 승인과 엄격한 절차를 모든 작은 수정에 적용하면 사용자의 흐름을 끊을 수 있습니다.',
 '현재 README는 대화→명세→구현 계획 흐름을 설명합니다. 공개 릴리스에는 brainstorming 조정과 컨텍스트 압축 이후에도 스킬이 유지되도록 한 개선이 나타납니다. 도구 소개 자체를 생산성 우위의 독립 증거로 보지는 않았습니다.',
 ['요구사항과 구현의 연결을 명시해 대화의 결과가 코드에서 빠지는 것을 줄입니다.','재현과 검증을 완료 주장에 연결하는 방식이 에이전트의 성급한 완료를 점검합니다.'],
 ['gstack과 전체 워크플로우를 중복 설치하면 같은 단계가 여러 번 실행됩니다.','문구·스타일 조정에까지 일률적인 사전 실패 테스트를 요구하면 가치가 낮은 테스트가 늘 수 있습니다.'],[
 ('깊이 있는 대화를 실행 명세로 남기기','확정 요구와 미확정 가정·제외 범위를 짧게 구분하고 구현의 인수 조건으로 연결합니다.','신규 기능과 복잡한 변경.','요구사항→계획→결과에서 빠진 항목이 없는지 대조.','채택 후보'),
 ('중요한 동작에는 실패 재현 후 수정','회귀 위험이 있는 로직은 실패 원인을 확인하고 최소 수정 후 다시 검증합니다.','데이터·권한·상태 전이·버그 수정.','설정 오류가 아닌 실제 동작 실패를 테스트가 잡는지 확인.','조건부'),
 ('방법론 중복은 제거','gstack을 기본 경로로 유지하고 Superpowers에서 필요한 검증/명세 습관만 채택합니다.','둘 이상의 개발 방법 플러그인을 결합할 때.','사용자에게 같은 결정을 반복 확인하지 않음.','프로젝트 맞춤 해석')])
add('peter','Peter Steinberger','실전 자동화 · 도구 규칙 · 스킬 관리','Agent Scripts에 자신의 여러 작업 공간에서 쓰는 지침과 헬퍼를 공개.','steipete/agent-scripts',
 '반복되는 실제 행동을 작고 실행 가능한 스킬·스크립트로 만드는 사례입니다. 개인 머신의 경로·앱·릴리스 규칙을 그대로 복제하기보다 재사용 가능한 동작 단위만 차용해야 합니다.',
 'README는 공통 AGENTS.MD, skills, 가벼운 헬퍼와 검증 훅을 원본으로 명시합니다. 에이전트별 발견 경로와 이름 충돌·실제 사용자 파일 보존도 설명합니다. 공개 저장소는 개인 사용 지침의 근거이며 모든 개발 대화 기록은 아닙니다.',
 ['작은 스크립트로 반복 작업을 고정하면 프롬프트마다 절차를 재발명하지 않습니다.','개별 지식은 짧게 유지하고 구체적인 도구 사용은 스크립트로 분리하는 구성이 실용적입니다.'],
 ['개인 툴 체인·브라우저·머신 경로에 의존하는 부분은 이 환경에서 바로 작동하지 않을 수 있습니다.','원본 지침 전체를 전역 설치하면 기존 저장소의 권한·배포·문체 규칙과 충돌할 수 있습니다.'],[
 ('반복된 수정은 작은 실행 도구로 만들기','반복되는 캡처·검사·자료 정제를 재실행 가능한 스크립트로 분리합니다.','같은 문제를 두 번 이상 고치거나 정기적으로 수행할 때.','스크립트를 다시 실행해 같은 조건의 결과를 얻을 수 있음.','채택 후보'),
 ('스킬은 선택 호출하고 기존 설정 보존','주제별 발견 가능한 설명과 짧은 본문을 유지하고 설치 시 실제 사용자 파일을 덮어쓰지 않습니다.','여러 저장소·에이전트에 개인 개발 지식을 배포할 때.','기존 AGENTS.md 보존과 재설치 멱등성을 테스트.','채택 후보'),
 ('머신 전용 규칙을 개인 기본값으로 복제하지 않기','특정 앱·경로·운영 권한이 필요한 도구는 적용 조건을 별도 기록합니다.','브라우저 자동화·릴리스·외부 서비스 연동.','현재 환경에서 도구·권한이 없을 때 올바르게 차단/대체됨.','조건부')])
add('andrej','Andrej Karpathy','자율 실험 · 평가 기준 · 개선 루프','Autoresearch 작성자. 제한된 학습 실험을 자동 반복하는 공개 실험.','karpathy/autoresearch',
 '“고쳐 보고 수치와 결과를 비교해 더 나을 때 남긴다”는 폐쇄 루프를 개인 개발 규칙 평가에 응용할 수 있습니다. 이 도구가 사용자의 취향을 자동 학습하거나 웹 앱 품질을 보장하는 것은 아닙니다.',
 '2026년 3월 공개 프로젝트는 제한된 학습 코드와 고정된 짧은 실험 시간을 사용하고 program.md로 실험의 조직 방식을 지정합니다. 원래 대상은 모델 학습이며 개인 UI 취향 최적화와는 다릅니다.',
 ['개선 후보와 평가 기준을 나누면 AI가 자기 주장을 근거로 규칙을 강화하는 문제를 줄입니다.','성공/실패 결과를 비교해 보존 또는 폐기하는 관점이 개인 규칙 버전 관리에 유용합니다.'],
 ['단일 점수 최적화는 가독성·취향·접근성 등 점수 밖 가치를 해칠 수 있습니다.','사용자 선호가 변하거나 작은 표본에 과적합하면 자동 반복이 잘못된 규칙을 강화합니다.','GitHub 메타데이터에서 라이선스를 확인하지 못했으므로 코드 반입 근거로 사용하지 않습니다.'],[
 ('규칙 변경을 실험으로 취급','후보 규칙, 기대 개선, 회귀 사례를 먼저 정하고 적용 전후 결과를 비교합니다.','반복된 사용자 지적을 기본 개발 규칙으로 승격할 때.','유사 요청에서 수정 지시가 줄고 기존 선호의 회귀가 없는지 확인.','프로젝트 맞춤 해석'),
 ('최종 만족을 단일 자동 점수로 대체하지 않기','기능 검증·화면 비교·사용자 판단을 구분해 기록합니다.','UI/UX·카피·작업 방식의 개인화.','테스트 통과와 사용자 수용 여부를 별도 필드로 남김.','프로젝트 맞춤 해석'),
 ('무제한 자기수정 대신 후보·승인·되돌리기','평가가 있는 후보만 버전화해 채택하고 반례가 나오면 이전 버전으로 되돌립니다.','지속 개선 기능.','거절/대체 이력과 당시 적용 규칙을 재구성 가능.','조건부')], [('고정 실험과 변경 경계를 정한 program.md','https://github.com/karpathy/autoresearch/blob/master/program.md')])
add('emil','Emil Kowalski','UI 디테일 · 인터랙션 · 모션','Design Engineer. 공개 모션 해설과 Vaul 변경 기록을 제공.','emilkowalski/vaul',
 '사용자 행동의 출발점과 기능적 맥락에 맞춰 움직임을 결정하는 원칙이 유용합니다. 모션은 제품을 돕는 수단이며 모든 화면을 애니메이션으로 채우는 처방으로 적용하면 안 됩니다.',
 'Good vs Great Animations는 트리거 기준 origin, easing, spring, 느린 재생/프레임 관찰을 설명하며 기능적 그래프에는 움직임이 오히려 불필요할 수 있다고 구분합니다. Vaul 현재 README는 유지보수 중단을 명시합니다.',
 ['열리는 대상이 어디서 왔는지 보여 주는 전환은 공간 관계를 이해하는 데 도움이 됩니다.','동작을 느리게 관찰해 전환 중의 어색함을 잡는 방법이 캡처 중심 QA를 보완합니다.'],
 ['모든 상호작용에 spring을 붙이면 빠른 입력과 실제 값 판독을 방해할 수 있습니다.','Vaul의 아이디어와 패키지의 현재 유지보수 상태를 분리해야 합니다. 신규 필수 의존성 채택은 권하지 않습니다.'],[
 ('모션을 트리거·공간 관계와 맞추기','팝오버/확장은 실제 트리거 위치와 방향을 반영하고 최종 상태의 즉시 사용을 보장합니다.','드롭다운·상세 패널·선택 전환.','클리핑·반복 입력·ESC·포커스 복귀와 reduced motion 확인.','채택 후보'),
 ('모션 QA는 전환 중간도 확인','시작/끝 화면뿐 아니라 느린 재생·중간 프레임으로 글자와 위치 관계를 점검합니다.','전환·숫자/차트·드로어 모션.','중간 상태의 텍스트 대비·겹침·입력 가능 상태가 유지됨.','채택 후보'),
 ('Vaul 신규 필수 의존성은 보류','아이디어는 참고하되 유지보수 중단 패키지를 표준 설치 목록에 넣지 않습니다.','새 프로젝트의 모션/드로어 도구 선정.','현재 유지보수와 대체 컴포넌트 동작을 비교.','제외 권고: 필수 패키지 채택')], [('작성자의 실제 모션 판단 예시','https://emilkowal.ski/ui/good-vs-great-animations'),('Vaul 공개 릴리스 수정 내역','https://github.com/emilkowalski/vaul/releases')])
add('sebastian','Sebastián Ramírez / FastAPI 팀','백엔드 API · 데이터 계약 · 컨테이너','FastAPI 개발자와 공식 Full Stack Template 유지보수 팀. 개인 일기보다 팀의 구현 근거로 평가.','fastapi/full-stack-fastapi-template',
 '데이터 검증·API 계약·DB·실제 E2E·Compose를 연결한 참고 구현입니다. 개인용 SQLite 검토 앱에 템플릿의 모든 인증·DB·메일·프록시 구성까지 넣을 필요는 없습니다.',
 '공식 템플릿에는 FastAPI, Pydantic, SQLModel, PostgreSQL, 생성 클라이언트, Playwright, Docker Compose가 명시돼 있습니다. 현재의 팀 저장소 상태이며 모든 설계 결정을 Sebastián 개인 경험으로 환원하지 않았습니다.',
 ['입력 모델과 API 계약을 명시하면 UI가 잘못된 데이터나 상태를 보내는 문제를 잡기 좋습니다.','Compose·API·브라우저 검증을 함께 보는 구성이 컨테이너 필수 하네스와 맞습니다.'],
 ['템플릿 전체 채택은 단일 사용자 앱에 불필요한 서비스와 운영 부담을 추가할 수 있습니다.','타입 검증만으로 권한·동시 수정·중복 실행·트랜잭션 정합성이 해결되지는 않습니다.'],[
 ('기능 경계마다 입력·결과 계약 정의','Pydantic 모델로 입력 범위·타입을 검증하고 API의 상태·오류를 일관되게 반환합니다.','회의/할 일/판단 이력 API.','잘못된 상태·없는 규칙·과도한 입력을 거부하며 기존 기록 보존.','채택 후보'),
 ('API·DB·UI를 실제 컨테이너에서 검증','Dockerfile·Compose·healthcheck와 영속 데이터 경로를 기능 완료 기준에 포함합니다.','모든 신규 서비스. MLX Metal 엔진만 승인 예외.','빌드→기동→기능 호출→재시작 후 데이터 보존 확인.','채택 후보'),
 ('SQLite부터 시작하고 필요 시 DB 확장','개인용 단일 서비스는 SQLite 트랜잭션으로 시작하고 동시성·운영 요구가 커질 때 PostgreSQL을 검토합니다.','개인 판단 기록·소규모 단일 사용자 앱.','동시 수정 충돌·재시작·백업·이력 보존 검증.','프로젝트 맞춤 해석: 템플릿의 기본 DB는 PostgreSQL')], [('Pydantic 요청 본문 검증','https://fastapi.tiangolo.com/tutorial/body/'),('공식 템플릿의 Compose 배포','https://github.com/fastapi/full-stack-fastapi-template/blob/master/deployment-docker-compose.md')])
add('adam','Adam Wathan / Tailwind CSS 팀','UI 시스템 · 타이포 · 간격 · 토큰','Tailwind CSS 공동 창업자와 유지보수 팀. 팀의 공개 시스템·구현을 근거로 검토.','tailwindlabs/tailwindcss',
 '색·간격·타입을 작은 공통 토큰으로 관리하는 방식은 일관된 UI를 만드는 데 유용합니다. Tailwind 자체가 정보 구조나 좋은 취향을 결정해 주지는 않습니다.',
 '현재 공식 문서는 theme variables와 대응 유틸리티를 연결합니다. 공개 저장소는 프레임워크 변경을 제공하며 저자의 모든 디자인 판단 기록은 아닙니다. Tailwind Plus/Refactoring UI 유료 자료는 열람·복제하지 않았습니다.',
 ['디자인 토큰이 분산된 임의 값보다 조정과 일관성 유지에 유리합니다.','기존 컴포넌트를 통해 변경을 전파하면 사용자의 수정 지시를 다음 화면에도 반영하기 쉽습니다.'],
 ['유틸리티를 많이 쓰는 것이 좋은 디자인이라는 판단은 성립하지 않습니다.','토큰을 전역 강제하거나 카드/색/밀도를 고정하면 각 사용 사례의 차이를 지우게 됩니다.'],[
 ('색·간격·타입의 공통 기준 유지','제품에 필요한 소수의 의미 있는 디자인 토큰을 정하고 공유 컴포넌트에서 사용합니다.','같은 제품의 여러 화면을 만들거나 반복 수정할 때.','토큰 수정이 관련 화면에 일관되게 반영되고 예외가 설명 가능.','채택 후보'),
 ('여백과 밀도는 사용자 과업으로 결정','같은 제품 안에서도 비교 표, 긴 읽기, 온보딩은 서로 다른 밀도를 허용합니다.','카드 중첩 제거와 업무 화면 구성.','중첩 경계를 덜어도 그룹·읽기 순서·터치 간격이 유지됨.','프로젝트 맞춤 해석'),
 ('프레임워크·유료 디자인 자산은 별도 판단','기존 CSS가 충분하면 새 프레임워크를 강제하지 않고 유료 자산을 오픈소스처럼 복제하지 않습니다.','신규 의존성·템플릿 선정.','사용 목적·설치 비용·라이선스와 기존 코드 적합성 확인.','조건부')], [('Theme variables 공식 문서','https://tailwindcss.com/docs/theme'),('애플리케이션 레이아웃 소개 · Adam Wathan','https://tailwindcss.com/blog/2024-05-24-catalyst-application-layouts')])
report=dict(version='2026-10-28.review-1',checked_at='2026-10-28',scope='선정한 공개 원본에 대한 1차 채택 검토. 객관적인 권위 순위나 모든 비공개 경험의 수집이 아님.',experts=experts)
(HERE/'catalog.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(f'{len(experts)} expert reports; {sum(len(e["rules"]) for e in experts)} separately reviewable rules')
